use serde_json::{json,Value};
use kfc_kfc_alpha::kfc::opcw::StringMap::StringMap;
use kfc_kfc_alpha::kfc::{opcw::{native::{PartRef,RelationRef},OpcwPackagePart::OpcwPackagePart},opcr::OpcRelation::OpcRelation,ooxfw::OxfwPackage::OxfwPackage,ooxfr::OxfPptRelations};
use std::{rc::Rc,io::{Cursor,Read,Write}};
fn relation(content:&str,kind:&str,name:&str)->RelationRef{RelationRef::Local(Rc::new(OpcRelation::OpcRelation(content,kind,name)))}
fn base64(s:&[u8])->String{let alphabet=b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";let mut out=String::new();for part in s.chunks(3){let v=((part[0]as u32)<<16)|((part.get(1).copied().unwrap_or(0)as u32)<<8)|part.get(2).copied().unwrap_or(0)as u32;for i in 0..4{out.push(if i>part.len(){'='}else{alphabet[((v>>(18-i*6))&63)as usize]as char});}}out}
#[test]
fn original_android_string_hashmap_tree_iteration(){
    let p=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("rewrite-review/milestones/m4-edit-save/evidence/package-r0b28");let java:Value=serde_json::from_slice(&std::fs::read(p.join("java.json")).unwrap()).unwrap();let mut actual=vec![];
    for (case,row)in java["maps"].as_array().unwrap().iter().enumerate(){let mut map=StringMap::default();let mut old=vec![];let mut snapshots=vec![];let stages=row["snapshots"].as_array().unwrap();for (i,key)in row["keys"].as_array().unwrap().iter().enumerate(){let previous=map.put(key.as_str().unwrap().into(),i);old.push(previous);if let Some(stage)=stages.iter().find(|s|s["after"]==i+1){let entries:Vec<_>=map.entrySet().map(|(k,v)|json!([k,v])).collect();let actual=json!({"after":i+1,"entries":entries});assert_eq!(actual,*stage,"case {case}, after {}",i+1);snapshots.push(actual);}}let actualRow=json!({"keys":row["keys"],"old":old,"snapshots":snapshots});assert_eq!(actualRow,*row,"case {case}");actual.push(actualRow);}
    std::fs::write(p.join("rust-maps.json"),serde_json::to_vec_pretty(&actual).unwrap()).unwrap();
}
#[test]
fn original_android_package_content_types_and_close(){
    let p=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("rewrite-review/milestones/m4-edit-save/evidence/package-r0b28");let java:Value=serde_json::from_slice(&std::fs::read(p.join("java.json")).unwrap()).unwrap();let out=p.join("zips");std::fs::create_dir_all(&out).unwrap();ss_core::java_runtime::KfsZip::install();let mut actual=vec![];
    for mask in 0..16{
        let file=out.join(format!("rust-{mask}.zip"));let mut pack=OxfwPackage::OxfwPackage(file.to_str().unwrap()).unwrap();let book=pack.createOfficeDocument(relation("application/book+xml","urn:book","/xl/workbook.xml"));let repeated=pack.createOfficeDocument(relation("other/type","urn:other","/other.xml"));let same=match(&book,&repeated){(PartRef::Base(a),PartRef::Base(b))=>Rc::ptr_eq(a,b),_=>false};let mut row=serde_json::json!({"sameOffice":same});
        book.getOutputStream().unwrap().unwrap().write_all(b"<workbook/>").unwrap();let rels=book.getRelationships();let sheet=rels.borrow_mut().addRelationship__2(relation("application/sheet+xml","urn:sheet","/xl/worksheets/sheet#.xml"),1).borrow_mut().createPart();sheet.getOutputStream().unwrap().unwrap().write_all(b"<sheet/>").unwrap();
        for i in 0..3{let image=sheet.getRelationships().borrow_mut().addRelationship__2(relation(&format!("image/png{i}"),"urn:image","/xl/media/image#.png"),i).borrow_mut().createPart();image.getOutputStream().unwrap().unwrap().write_all(format!("PNG{i}").as_bytes()).unwrap();if i==0{image.getRelationships().borrow_mut().addRelationship(relation("application/hidden+xml","urn:hidden","/xl/hidden.xml")).borrow_mut().createPart();}}
        let item=rels.borrow_mut().addRelationship__2(RelationRef::Local(Rc::new(OxfPptRelations::ITEM())),1).borrow_mut().createPart();item.getOutputStream().unwrap().unwrap().write_all(b"<custom/>").unwrap();item.getRelationships().borrow_mut().addRelationship(relation("application/props+xml","urn:props","/customXml/props1.xml")).borrow_mut().createPart().getOutputStream().unwrap().unwrap().write_all(b"<props/>").unwrap();
        for name in ["/xl/control.vml","/xl/upper.XML","/xl/noextension"]{rels.borrow_mut().addRelationship(relation("application/odd","urn:odd",name)).borrow_mut().createPart().getOutputStream().unwrap().unwrap().write_all(name.as_bytes()).unwrap();}rels.borrow_mut().addRelationship(relation("application/uncreated+xml","urn:uncreated","/xl/uncreated.xml"));
        if mask&1!=0{let app=pack.getAppPart();row["sameApp"]=json!(Rc::ptr_eq(&app,&pack.getAppPart()));app.borrow_mut().setCompany(Some("公司".into()));}
        if mask&2!=0{let core=pack.getCorePart();row["sameCore"]=json!(Rc::ptr_eq(&core,&pack.getCorePart()));core.borrow_mut().setCreator(Some("作者".into()));core.borrow_mut().setCreated(Some(1735689600000));}
        if mask&4!=0{row["sameCustom"]=json!(Rc::ptr_eq(&pack.getCustomPart(),&pack.getCustomPart()));}
        if mask&8!=0{for i in 0..32{let extension=(0..5).map(|b|if i&(1<<b)==0{"Aa"}else{"BB"}).collect::<String>();rels.borrow_mut().addRelationship(relation(&format!("binary/{i}"),"urn:binary",&format!("/xl/data/data{i}.{extension}"))).borrow_mut().createPart().getOutputStream().unwrap().unwrap().write_all(&[i as u8]).unwrap();}}
        row["rootRels"]=json!(pack.getRelationships().borrow().size());pack.close().unwrap();let bytes=std::fs::read(&file).unwrap();let mut zip=zip::ZipArchive::new(Cursor::new(bytes)).unwrap();let mut entries=vec![];for i in 0..zip.len(){let mut e=zip.by_index(i).unwrap();let mut b=vec![];e.read_to_end(&mut b).unwrap();entries.push(json!({"name":e.name(),"method":e.compression().to_u16(),"size":e.size(),"crc":e.crc32(),"bytes":base64(&b)}));}row["entries"]=json!(entries);row["secondClose"]=json!(match pack.close(){Ok(())=>"ok",Err(e)=>kfs_kfs_app::kfs::zip::ZipErrors::javaExceptionName(&e)});assert_eq!(row,java["packages"][mask as usize],"mask {mask}");actual.push(row);
    }
    std::fs::write(p.join("rust-packages.json"),serde_json::to_vec_pretty(&actual).unwrap()).unwrap();
}
fn zip_entries(file:&std::path::Path)->Value{let bytes=std::fs::read(file).unwrap();let mut zip=zip::ZipArchive::new(Cursor::new(bytes)).unwrap();let mut entries=vec![];for i in 0..zip.len(){let mut e=zip.by_index(i).unwrap();let mut b=vec![];e.read_to_end(&mut b).unwrap();entries.push(json!({"name":e.name(),"method":e.compression().to_u16(),"size":e.size(),"crc":e.crc32(),"bytes":base64(&b)}));}json!(entries)}
fn panic_name(e:Box<dyn std::any::Any+Send>)->String{let text=e.downcast_ref::<String>().cloned().or_else(||e.downcast_ref::<&str>().map(|s|s.to_string())).unwrap_or_default();for name in ["IllegalArgumentException","RuntimeException"]{if text.contains(name){return name.into();}}panic!("unexpected panic {text}")}
#[test]
fn original_android_package_finally_and_duplicate_entry_errors(){
    use kfc_kfc_alpha::kfc::opcw::OpcwPackage::OpcwPackage;
    let p=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("rewrite-review/milestones/m4-edit-save/evidence/package-r0b28");let java:Value=serde_json::from_slice(&std::fs::read(p.join("java.json")).unwrap()).unwrap();let out=p.join("zips");std::fs::create_dir_all(&out).unwrap();ss_core::java_runtime::KfsZip::install();let mut actual=vec![];
    for mode in 0..3{let file=out.join(format!("rust-error-{mode}.zip"));let mut pack=OpcwPackage::OpcwPackage(file.to_str().unwrap()).unwrap();let mut row=json!({});if mode!=2{let part=pack.createOfficeDocument(relation("application/main+xml","urn:main","/a/b/c.xml"));part.getOutputStream().unwrap().unwrap().write_all(&[65]).unwrap();if mode==0{part.getRelationships().borrow_mut().addRelationship(relation("application/other+xml","urn:other","/x/y/z.xml")).borrow_mut().createPart();}else{row["write"]=json!(match part.getOutputStream(){Ok(_)=>"ok",Err(e)=>kfs_kfs_app::kfs::zip::ZipErrors::javaExceptionName(&e)});}}
        let close=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||pack.close()));row["close"]=json!(match close{Ok(Ok(()))=>"ok".into(),Ok(Err(e))=>kfs_kfs_app::kfs::zip::ZipErrors::javaExceptionName(&e).into(),Err(e)=>panic_name(e)});row["secondClose"]=json!(match pack.close(){Ok(())=>"ok",Err(e)=>kfs_kfs_app::kfs::zip::ZipErrors::javaExceptionName(&e)});row["entries"]=zip_entries(&file);assert_eq!(row,java["errors"][mode],"error mode {mode}");actual.push(row);
    }std::fs::write(p.join("rust-errors.json"),serde_json::to_vec_pretty(&actual).unwrap()).unwrap();
}
